edits.replacement:
.ocacts::before{ content:''; position:absolute; left:0; right:0; top:-14px; height:14px; pointer-events:none;   /* v19.50, from the review (2026-10-08): inside the 14px gap above the row, so on a card that does not scroll it no longer veils the note box */
  background:linear-gradient(180deg,rgba(0,0,0,0),var(--win-bot)); }
/* v16.xx, from the whole-game bug hunt of 2026-10-08 (W-E1), seen on the 4K run card screenshots: THE BUTTON STRIP RUNS THE
   FULL WIDTH OF THE CARD. The solid strip under the two buttons stopped at the card's 52 px side margins, and its flat colour is
   a shade off the card's own light from the top, so on every death and extract card it showed as a faint box inset behind LOG
   RUN AND RETURN and COPY REPORT. It now reaches both edges of the card, so the box has no sides to see. The buttons, the fade
   above them and the pinning on a card that scrolls are unchanged, and the card never scrolls sideways for it. */
.ocacts{ width:calc(100% + 104px); margin-left:-52px; margin-right:-52px; }
.ocwin{ overflow-x:hidden; }

check:
{v:'VER',what:'the run card button strip runs the full width of the card, so it never shows as a box inset behind the two buttons, and the card does not scroll sideways for it',
 run:function(){
   var oc=document.getElementById('outcome'), w=oc&&oc.querySelector('.ocwin'), a=oc&&oc.querySelector('.ocacts'), was=oc&&oc.classList.contains('on'), bad=[], cw, gl, gr;
   if(!oc||!w||!a) return 'SKIP: no run card here';
   try{
     oc.classList.add('on');
     cw=w.clientWidth;
     if(!(cw>200&&a.offsetWidth>50)) return 'SKIP: the run card is not laid out ('+cw+' wide)';
     if(a.offsetParent!==w) return 'SKIP: the button strip is not measured from the card here';
     gl=a.offsetLeft; gr=cw-(a.offsetLeft+a.offsetWidth);
     if(gl>3) bad.push('the button strip starts '+gl+' px in from the left edge of the card, so it shows as a box behind the buttons');
     if(gr>3) bad.push('the button strip stops '+gr+' px short of the right edge of the card');
     if(w.scrollWidth>cw+1) bad.push('the card scrolls sideways ('+w.scrollWidth+' of content in '+cw+')');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ if(!was) oc.classList.remove('on'); }
   return bad.length?bad.join('; '):null; }},
